      backup_text =
        "# NIGHT GARDEN HARVEST LEDGER #\n\
         # Track your harvest under the stars! #\n\
         # Consecutive harvests of the same quality build streak bonuses #\n\n\
         # Quality tiers from the moonlit fields #\n\
         type Quality =\n\
        \  + Bronze      # Common harvest, basic value #\n\
        \  + Silver      # Good quality, moderate bonus #\n\
        \  + Gold        # Excellent harvest, high value #\n\
        \  + Starlight   # Legendary, blessed by the moon #\n\
         in\n\n\
         # Crops that grow under the night sky #\n\
         type Crop =\n\
        \  + Moonmelon\n\
        \  + Starfruit\n\
        \  + Nightshade\n\
        \  + Glowpumpkin\n\
        \  + Duskwheat\n\
         in\n\n\
         # A single harvest from the garden #\n\
         type Harvest = (\n\
        \  crop = Crop,\n\
        \  quality = Quality,\n\
        \  quantity = Int\n\
         ) in\n\n\
         # The harvest ledger tracks all harvests and bonuses #\n\
         type Model = (\n\
        \  harvests = [Harvest],\n\
        \  totalValue = Int,\n\
        \  streakBonus = Int,\n\
        \  lastQuality = Quality\n\
         ) in\n\n\
         # Actions the farmer can take #\n\
         type Action =\n\
        \  + RecordHarvest(Harvest)  # Log a new harvest #\n\
        \  + ClaimBonus              # Collect accumulated streak bonus #\n\
        \  + CloseDay                # End the harvest day, reset streaks #\n\
         in\n\n\
         let cropValue(c: Crop): Int =\n\
        \  case c\n\
        \  | Moonmelon => 15\n\
        \  | Starfruit => 20\n\
        \  | Nightshade => 20\n\
        \  | Glowpumpkin => 12\n\
        \  | Duskwheat => 10\n\
        \  end\n\
         in\n\n\
         let qualityMultiplier(q: Quality): Int =\n\
        \  case q\n\
        \  | Bronze => 1\n\
        \  | Silver => 2\n\
        \  | Gold => 3\n\
        \  | Starlight => 5\n\
        \  end\n\
         in\n\n\
         let harvestValue(h: Harvest): Int =\n\
        \  cropValue(h.crop) * qualityMultiplier(h.quality) * h.quantity\n\
         in\n\n\
         let init: Model = (\n\
        \  harvests = [],\n\
        \  totalValue = 0,\n\
        \  streakBonus = 0,\n\
        \  lastQuality = Bronze\n\
         ) in\n\n\
         # A streak continues when consecutive harvests share a quality tier #\n\
         let processHarvest(ledger: Model, h: Harvest): Model =\n\
        \  let value = harvestValue(h) in\n\
        \  let isFirst = length(ledger.harvests) == 0 in\n\
        \  let continues = !isFirst && h.quality == ledger.lastQuality in\n\
        \  let newStreak = if continues then ledger.streakBonus + 5 else 0 in\n\
        \  (\n\
        \    harvests = h :: ledger.harvests,\n\
        \    totalValue = ledger.totalValue + value + newStreak,\n\
        \    streakBonus = newStreak,\n\
        \    lastQuality = h.quality\n\
        \  )\n\
         in\n\n\
         let claimBonus(ledger: Model): Model =\n\
        \  (\n\
        \    harvests = ledger.harvests,\n\
        \    totalValue = ledger.totalValue + ledger.streakBonus,\n\
        \    streakBonus = 0,\n\
        \    lastQuality = ledger.lastQuality\n\
        \  )\n\
         in\n\n\
         # Close the harvest day: keep the ledger, reset streak tracking #\n\
         let closeDay(ledger: Model): Model =\n\
        \  (\n\
        \    harvests = ledger.harvests,\n\
        \    totalValue = ledger.totalValue,\n\
        \    streakBonus = 0,\n\
        \    lastQuality = Bronze\n\
        \  )\n\
         in\n\n\
         let update(action: Action, ledger: Model): (Model, Cmd) =\n\
        \  case action\n\
        \  | RecordHarvest(h) => (processHarvest(ledger, h), CmdNone)\n\
        \  | ClaimBonus => (claimBonus(ledger), CmdNone)\n\
        \  | CloseDay => (closeDay(ledger), CmdNone)\n\
        \  end\n\
         in\n\n\
         # ===== VIEW HELPERS ===== #\n\n\
         let cropName(c: Crop): String =\n\
        \  case c\n\
        \  | Moonmelon => \"Moonmelon\"\n\
        \  | Starfruit => \"Starfruit\"\n\
        \  | Nightshade => \"Nightshade\"\n\
        \  | Glowpumpkin => \"Glowpumpkin\"\n\
        \  | Duskwheat => \"Duskwheat\"\n\
        \  end\n\
         in\n\n\
         let qualityLabel(q: Quality): String =\n\
        \  case q\n\
        \  | Bronze => \"Bronze\"\n\
        \  | Silver => \"Silver\"\n\
        \  | Gold => \"Gold\"\n\
        \  | Starlight => \"Starlight\"\n\
        \  end\n\
         in\n\n\
         let qualityEmoji(q: Quality): String =\n\
        \  case q\n\
        \  | Bronze => \"\240\159\165\137\"\n\
        \  | Silver => \"\240\159\165\136\"\n\
        \  | Gold => \"\240\159\165\135\"\n\
        \  | Starlight => \"\226\173\144\"\n\
        \  end\n\
         in\n\n\
         let qualityColor(q: Quality): String =\n\
        \  case q\n\
        \  | Bronze => \"#cd7f32\"\n\
        \  | Silver => \"#c0c0c0\"\n\
        \  | Gold => \"#ffd700\"\n\
        \  | Starlight => \"#e0b0ff\"\n\
        \  end\n\
         in\n\n\
         # ===== VIEW ===== #\n\n\
         let view(model: Model): HTML =\n\
        \  let harvestRows =\n\
        \    let ordered = reverse(model.harvests) in\n\
        \    mapi(ordered, fun (i, h) ->\n\
        \      Tr(\n\
        \        [Style([(\"border-bottom\", \"1px solid #21262d\")])],\n\
        \        [\n\
        \          Td(\n\
        \            [Style([(\"padding\", \"8px 12px\"), (\"color\", \
         \"#8b949e\")])],\n\
        \            [Text(string_of_int(i + 1))]\n\
        \          ),\n\
        \          Td(\n\
        \            [Style([(\"padding\", \"8px 12px\"), (\"color\", \
         \"#c9d1d9\")])],\n\
        \            [Text(cropName(h.crop))]\n\
        \          ),\n\
        \          Td(\n\
        \            [Style([(\"padding\", \"8px 12px\"), (\"color\", \
         qualityColor(h.quality))])],\n\
        \            [Text(qualityEmoji(h.quality) ++ \" \" ++ \
         qualityLabel(h.quality))]\n\
        \          ),\n\
        \          Td(\n\
        \            [Style([(\"padding\", \"8px 12px\"), (\"color\", \
         \"#c9d1d9\"), (\"text-align\", \"right\")])],\n\
        \            [Text(string_of_int(h.quantity))]\n\
        \          ),\n\
        \          Td(\n\
        \            [Style([(\"padding\", \"8px 12px\"), (\"color\", \
         \"#58a6ff\"), (\"text-align\", \"right\"), (\"font-weight\", \
         \"bold\")])],\n\
        \            [Text(string_of_int(harvestValue(h)))]\n\
        \          )\n\
        \        ]\n\
        \      )\n\
        \    )\n\
        \  in\n\
        \  let harvestButton(h: Harvest): HTML =\n\
        \    Button(\n\
        \      [OnClick(RecordHarvest(h)),\n\
        \       Style([(\"padding\", \"8px 14px\"), (\"background\", \
         \"#21262d\"), (\"color\", qualityColor(h.quality)),\n\
        \              (\"border\", \"1px solid #30363d\"), \
         (\"border-radius\", \"6px\"),\n\
        \              (\"cursor\", \"pointer\"), (\"font-family\", \
         \"monospace\"), (\"font-size\", \"12px\")])],\n\
        \      [Text(qualityEmoji(h.quality) ++ \" \" ++ cropName(h.crop) ++ \
         \" x\" ++ string_of_int(h.quantity))]\n\
        \    )\n\
        \  in\n\
        \  let headerCell(label: String, align: String): HTML =\n\
        \    Th([Style([(\"padding\", \"8px 12px\"), (\"text-align\", align), \
         (\"color\", \"#8b949e\"),\n\
        \               (\"font-size\", \"11px\"), (\"text-transform\", \
         \"uppercase\")])],\n\
        \       [Text(label)])\n\
        \  in\n\
        \  let statBlock(label: String, color: String, value: String): HTML =\n\
        \    Div(\n\
        \      [Style([(\"text-align\", \"center\")])],\n\
        \      [\n\
        \        Div([Style([(\"font-size\", \"11px\"), (\"color\", \
         \"#8b949e\"), (\"margin-bottom\", \"4px\")])],\n\
        \            [Text(label)]),\n\
        \        Div([Style([(\"font-size\", \"24px\"), (\"color\", color), \
         (\"font-weight\", \"bold\")])],\n\
        \            [Text(value)])\n\
        \      ]\n\
        \    )\n\
        \  in\n\
        \  Div(\n\
        \    [Style([\n\
        \      (\"max-width\", \"600px\"), (\"margin\", \"20px auto\"), \
         (\"font-family\", \"monospace\"),\n\
        \      (\"background\", \"#0d1117\"), (\"padding\", \"24px\"), \
         (\"border-radius\", \"12px\"),\n\
        \      (\"color\", \"#c9d1d9\"), (\"border\", \"1px solid #30363d\")\n\
        \    ])],\n\
        \    [\n\
        \      H1(\n\
        \        [Style([(\"text-align\", \"center\"), (\"color\", \
         \"#e0b0ff\"), (\"margin-bottom\", \"4px\"), (\"font-size\", \
         \"24px\")])],\n\
        \        [Text(\"\240\159\140\153 Harvest Ledger \240\159\140\153\")]\n\
        \      ),\n\
        \      P(\n\
        \        [Style([(\"text-align\", \"center\"), (\"color\", \
         \"#8b949e\"), (\"margin-top\", \"0\"), (\"font-size\", \"12px\")])],\n\
        \        [Text(\"Track your night garden harvests\")]\n\
        \      ),\n\
        \      Hr([Style([(\"border\", \"none\"), (\"border-top\", \"1px solid \
         #21262d\"), (\"margin\", \"16px 0\")])]),\n\n\
        \      # Summary stats #\n\
        \      Div(\n\
        \        [Style([(\"display\", \"flex\"), (\"justify-content\", \
         \"space-around\"), (\"margin-bottom\", \"20px\"),\n\
        \                (\"padding\", \"12px\"), (\"background\", \
         \"#161b22\"), (\"border-radius\", \"8px\"),\n\
        \                (\"border\", \"1px solid #21262d\")])],\n\
        \        [\n\
        \          statBlock(\"TOTAL VALUE\", \"#58a6ff\", \
         string_of_int(model.totalValue)),\n\
        \          statBlock(\"STREAK BONUS\",\n\
        \                    if model.streakBonus > 0 then \"#3fb950\" else \
         \"#484f58\",\n\
        \                    \"+\" ++ string_of_int(model.streakBonus)),\n\
        \          statBlock(\"LAST QUALITY\", \
         qualityColor(model.lastQuality), qualityEmoji(model.lastQuality))\n\
        \        ]\n\
        \      ),\n\n\
        \      # Harvest table #\n\
        \      Table(\n\
        \        [Style([(\"width\", \"100%\"), (\"border-collapse\", \
         \"collapse\"), (\"margin-bottom\", \"20px\")])],\n\
        \        [\n\
        \          Thead(\n\
        \            [Style([(\"border-bottom\", \"2px solid #30363d\")])],\n\
        \            [\n\
        \              Tr(\n\
        \                [],\n\
        \                [\n\
        \                  headerCell(\"#\", \"left\"),\n\
        \                  headerCell(\"Crop\", \"left\"),\n\
        \                  headerCell(\"Quality\", \"left\"),\n\
        \                  headerCell(\"Qty\", \"right\"),\n\
        \                  headerCell(\"Value\", \"right\")\n\
        \                ]\n\
        \              )\n\
        \            ]\n\
        \          ),\n\
        \          Tbody(\n\
        \            [],\n\
        \            if length(model.harvests) == 0\n\
        \            then [\n\
        \              Tr([], [\n\
        \                Td(\n\
        \                  [Style([(\"padding\", \"20px\"), (\"text-align\", \
         \"center\"), (\"color\", \"#484f58\"), (\"font-style\", \
         \"italic\")])],\n\
        \                  [Text(\"No harvests yet... the garden awaits\")]\n\
        \                )\n\
        \              ])\n\
        \            ]\n\
        \            else harvestRows\n\
        \          )\n\
        \        ]\n\
        \      ),\n\n\
        \      # Record-harvest buttons #\n\
        \      Div(\n\
        \        [Style([(\"display\", \"flex\"), (\"flex-wrap\", \"wrap\"), \
         (\"gap\", \"8px\"), (\"margin-bottom\", \"12px\")])],\n\
        \        [\n\
        \          H3([Style([(\"width\", \"100%\"), (\"color\", \"#e0b0ff\"), \
         (\"font-size\", \"14px\"), (\"margin\", \"4px 0\")])],\n\
        \             [Text(\"\240\159\140\153 Record Harvest\")]),\n\
        \          harvestButton((crop = Moonmelon, quality = Bronze, quantity \
         = 2)),\n\
        \          harvestButton((crop = Starfruit, quality = Silver, quantity \
         = 1)),\n\
        \          harvestButton((crop = Nightshade, quality = Gold, quantity \
         = 1)),\n\
        \          harvestButton((crop = Glowpumpkin, quality = Gold, quantity \
         = 3)),\n\
        \          harvestButton((crop = Duskwheat, quality = Bronze, quantity \
         = 4)),\n\
        \          harvestButton((crop = Moonmelon, quality = Starlight, \
         quantity = 1))\n\
        \        ]\n\
        \      ),\n\n\
        \      # Ledger actions #\n\
        \      Div(\n\
        \        [Style([(\"display\", \"flex\"), (\"gap\", \"8px\"), \
         (\"margin-top\", \"8px\")])],\n\
        \        [\n\
        \          Button(\n\
        \            [OnClick(ClaimBonus),\n\
        \             Style([(\"padding\", \"8px 16px\"), (\"background\", \
         \"#238636\"), (\"color\", \"white\"),\n\
        \                    (\"border\", \"none\"), (\"border-radius\", \
         \"6px\"),\n\
        \                    (\"cursor\", \"pointer\"), (\"font-family\", \
         \"monospace\"), (\"font-size\", \"13px\")])],\n\
        \            [Text(\"\240\159\146\176 Claim Bonus\")]\n\
        \          ),\n\
        \          Button(\n\
        \            [OnClick(CloseDay),\n\
        \             Style([(\"padding\", \"8px 16px\"), (\"background\", \
         \"#8b2252\"), (\"color\", \"white\"),\n\
        \                    (\"border\", \"none\"), (\"border-radius\", \
         \"6px\"),\n\
        \                    (\"cursor\", \"pointer\"), (\"font-family\", \
         \"monospace\"), (\"font-size\", \"13px\")])],\n\
        \            [Text(\"\240\159\140\133 Close Day\")]\n\
        \          )\n\
        \        ]\n\
        \      ),\n\n\
        \      Div(\n\
        \        [Style([(\"text-align\", \"center\"), (\"color\", \
         \"#484f58\"), (\"font-size\", \"11px\"),\n\
        \                (\"margin-top\", \"16px\"), (\"padding-top\", \
         \"12px\"), (\"border-top\", \"1px solid #21262d\")])],\n\
        \        [Text(\"\240\159\140\177 Harvests: \" ++ \
         string_of_int(length(model.harvests)) ++ \" | Night Garden Ledger\")]\n\
        \      )\n\
        \    ]\n\
        \  )\n\
         in\n\n\
         let subs(_model: Model): Sub = SubNone in\n\n\
         # ===== TESTS ===== #\n\n\
         let step(acc: Model, a: Action): Model = let (m, _cmd) = update(a, \
         acc) in m in\n\
         let run(ledger: Model, actions: [Action]): Model = fold_left(actions, \
         step, ledger) in\n\n\
         hint \"recording harvest adds to total value\"\n\
         test\n\
        \  let h: Harvest = (crop = Moonmelon, quality = Bronze, quantity = 2) \
         in\n\
        \  let (ledger, _cmd) = update(RecordHarvest(h), init) in\n\
        \  # Moonmelon(15) * Bronze(1) * 2 = 30, no streak bonus on the first #\n\
        \  ledger.totalValue == 30\n\
         end;\n\n\
         hint \"harvest is added to harvests list\"\n\
         test\n\
        \  let h: Harvest = (crop = Starfruit, quality = Silver, quantity = 1) \
         in\n\
        \  let (ledger, _cmd) = update(RecordHarvest(h), init) in\n\
        \  length(ledger.harvests) == 1\n\
         end;\n\n\
         hint \"silver quality doubles value\"\n\
         test\n\
        \  let h: Harvest = (crop = Duskwheat, quality = Silver, quantity = 1) \
         in\n\
        \  let (ledger, _cmd) = update(RecordHarvest(h), init) in\n\
        \  ledger.totalValue == 20\n\
         end;\n\n\
         hint \"gold quality triples value\"\n\
         test\n\
        \  let h: Harvest = (crop = Duskwheat, quality = Gold, quantity = 1) in\n\
        \  let (ledger, _cmd) = update(RecordHarvest(h), init) in\n\
        \  ledger.totalValue == 30\n\
         end;\n\n\
         hint \"starlight quality gives 5x value\"\n\
         test\n\
        \  let h: Harvest = (crop = Nightshade, quality = Starlight, quantity \
         = 1) in\n\
        \  let (ledger, _cmd) = update(RecordHarvest(h), init) in\n\
        \  ledger.totalValue == 100\n\
         end;\n\n\
         hint \"same quality builds streak\"\n\
         test\n\
        \  let h1: Harvest = (crop = Moonmelon, quality = Gold, quantity = 1) in\n\
        \  let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
        \  let ledger = run(init, [RecordHarvest(h1), RecordHarvest(h2)]) in\n\
        \  ledger.streakBonus == 5\n\
         end;\n\n\
         hint \"streak bonus accumulates with consecutive same-quality \
         harvests\"\n\
         test\n\
        \  let h1: Harvest = (crop = Moonmelon, quality = Silver, quantity = \
         1) in\n\
        \  let h2: Harvest = (crop = Starfruit, quality = Silver, quantity = \
         1) in\n\
        \  let h3: Harvest = (crop = Nightshade, quality = Silver, quantity = \
         1) in\n\
        \  let ledger = run(init, [\n\
        \    RecordHarvest(h1),\n\
        \    RecordHarvest(h2),\n\
        \    RecordHarvest(h3)\n\
        \  ]) in\n\
        \  ledger.streakBonus == 10\n\
         end;\n\n\
         hint \"different quality resets streak\"\n\
         test\n\
        \  let h1: Harvest = (crop = Moonmelon, quality = Bronze, quantity = \
         1) in\n\
        \  let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
        \  let ledger = run(init, [RecordHarvest(h1), RecordHarvest(h2)]) in\n\
        \  ledger.streakBonus == 0\n\
         end;\n\n\
         hint \"streak resets then can build again\"\n\
         test\n\
        \  let h1: Harvest = (crop = Moonmelon, quality = Bronze, quantity = \
         1) in\n\
        \  let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
        \  let h3: Harvest = (crop = Nightshade, quality = Gold, quantity = 1) \
         in\n\
        \  let ledger = run(init, [\n\
        \    RecordHarvest(h1),\n\
        \    RecordHarvest(h2),\n\
        \    RecordHarvest(h3)\n\
        \  ]) in\n\
        \  ledger.streakBonus == 5\n\
         end;\n\n\
         hint \"claiming bonus banks it and resets the streak\"\n\
         test\n\
        \  let h1: Harvest = (crop = Moonmelon, quality = Gold, quantity = 1) in\n\
        \  let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
        \  let earned = run(init, [RecordHarvest(h1), RecordHarvest(h2)]) in\n\
        \  let ledger = run(earned, [ClaimBonus]) in\n\
        \  ledger.streakBonus == 0 && ledger.totalValue == earned.totalValue + 5\n\
         end;\n\n\
         hint \"closing day resets streak tracking\"\n\
         test\n\
        \  let h1: Harvest = (crop = Moonmelon, quality = Gold, quantity = 1) in\n\
        \  let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
        \  let ledger = run(init, [\n\
        \    RecordHarvest(h1),\n\
        \    RecordHarvest(h2),\n\
        \    CloseDay\n\
        \  ]) in\n\
        \  ledger.streakBonus == 0 && ledger.lastQuality == Bronze\n\
         end;\n\n\
         hint \"lastQuality tracks most recent harvest quality\"\n\
         test\n\
        \  let h: Harvest = (crop = Moonmelon, quality = Starlight, quantity = \
         1) in\n\
        \  let (ledger, _cmd) = update(RecordHarvest(h), init) in\n\
        \  ledger.lastQuality == Starlight\n\
         end;\n\n\
         hint \"starfruit and nightshade have the highest base value\"\n\
         test\n\
        \  let h1: Harvest = (crop = Nightshade, quality = Bronze, quantity = \
         1) in\n\
        \  let h2: Harvest = (crop = Moonmelon, quality = Bronze, quantity = \
         1) in\n\
        \  let (ledger1, _c1) = update(RecordHarvest(h1), init) in\n\
        \  let (ledger2, _c2) = update(RecordHarvest(h2), init) in\n\
        \  ledger1.totalValue > ledger2.totalValue &&\n\
        \  cropValue(Starfruit) == cropValue(Nightshade)\n\
         end;\n\n\
         hint \"duskwheat has the lowest base value\"\n\
         test\n\
        \  let h1: Harvest = (crop = Duskwheat, quality = Bronze, quantity = \
         1) in\n\
        \  let h2: Harvest = (crop = Glowpumpkin, quality = Bronze, quantity = \
         1) in\n\
        \  let (ledger1, _c1) = update(RecordHarvest(h1), init) in\n\
        \  let (ledger2, _c2) = update(RecordHarvest(h2), init) in\n\
        \  ledger1.totalValue < ledger2.totalValue\n\
         end;\n\n\
         hint \"quantity multiplies value\"\n\
         test\n\
        \  let h: Harvest = (crop = Moonmelon, quality = Bronze, quantity = 5) \
         in\n\
        \  let (ledger, _cmd) = update(RecordHarvest(h), init) in\n\
        \  ledger.totalValue == 75\n\
         end;\n\n\
         hint \"full harvest day scenario\"\n\
         test\n\
        \  let ledger = run(init, [\n\
        \    # Dusk: Bronze harvests build a streak #\n\
        \    RecordHarvest((crop = Duskwheat, quality = Bronze, quantity = 3)),\n\
        \    RecordHarvest((crop = Moonmelon, quality = Bronze, quantity = 2)),\n\
        \    # Midnight: switch to Gold, streak resets #\n\
        \    RecordHarvest((crop = Starfruit, quality = Gold, quantity = 1)),\n\
        \    RecordHarvest((crop = Nightshade, quality = Gold, quantity = 1)),\n\
        \    # Dawn: claim and close #\n\
        \    ClaimBonus,\n\
        \    CloseDay\n\
        \  ]) in\n\
        \  ledger.streakBonus == 0 &&\n\
        \  length(ledger.harvests) == 4\n\
         end;\n\n\
         (init, update, view, subs)\n";
      refractors = "()";
    } )
